      "claim": "A related isoxazole-containing benzenesulfonamide (compound 7z) achieved >80% oral availability in humans, supporting that the isoxazole-sulfonamide motif is well absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Valdecoxib, an isoxazole benzenesulfonamide, has 83% absolute oral bioavailability in humans, further supporting high F for the isoxazole-sulfonamide class.",
      "evidence_role": "supportive"
    }
